SELECT CASE WHEN balance >= 59000 THEN 'high' WHEN balance >= 24000 THEN 'mid' ELSE 'low' END AS balance_bucket, COUNT(balance) AS balance_count, SUM(CASE WHEN account_type = 'LOAN' THEN balance ELSE 0 END) AS loan_balance FROM accounts WHERE account_type = 'LOAN' OR customer_id = 23 GROUP BY CASE WHEN balance >= 59000 THEN 'high' WHEN balance >= 24000 THEN 'mid' ELSE 'low' END ORDER BY loan_balance, balance_bucket LIMIT 1
